function segmentDistance(p,a,b){let dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p.x-a[0])*dx+(p.y-a[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p.x-a[0]-t*dx,p.y-a[1]-t*dy)}
function nearRoad(p,pad=0){return roads.some(r=>r.pts.slice(1).some((b,i)=>segmentDistance(p,r.pts[i],b)<r.w/2+pad))}
function player(id,role){return{id,role,x:LZ.x-40+id*12,y:LZ.y+55,hp:100,ammo:roles[role].ammo,clip:30,reloading:0,stamina:100,parts:role==='engineer'?3:0,flares:roles[role].flares,kits:roles[role].kits,vehicle:null,turret:false,escaped:false,angle:0,cool:0,supplyAt:-99999,input:{x:0,y:0,ax:0,ay:0,fire:false},lastSeen:0}}
