if(act==='flare'&&p.flares>0){p.flares--;let dx=p.input.ax-p.x,dy=p.input.ay-p.y,d=Math.hypot(dx,dy)||1;state.strikes.push({x:Math.max(0,Math.min(W,p.x+dx/d*200)),y:Math.max(0,Math.min(H,p.y+dy/d*200)),timer:6});event('Red flare deployed. Airstrike inbound in 6 seconds. Clear the red ring!');}
if(act==='supply'){if(state.time-p.supplyAt<900){event('Supply helicopter rearming: 15 game-minute cooldown.');return}p.supplyAt=state.time;state.drops.push({x:p.x,y:p.y,timer:10,ready:false});event('Supply helicopter inbound. Drop in 10 seconds.');}
