function finish(deadline=false){if(deadline){state.players.filter(p=>!p.escaped).forEach(p=>p.hp=0);state.survivors.filter(s=>!['rescued','dead'].includes(s.status)).forEach(s=>{s.status='dead';state.lost++})}let escaped=state.players.filter(p=>p.escaped).length;state.result={win:state.rescued===40&&escaped===state.players.length,rescued:state.rescued,escaped,deadline};}
function boom(x,y,r,damage){fx.push({x,y,r,t:.7});pushEffect({x,y,r});sound('boom');state.zombies.forEach(z=>{if(dist(z,{x,y})<r)z.hp-=damage});state.vehicles.forEach(v=>{if(dist(v,{x,y})<r)v.hp-=damage});state.players.forEach(p=>{if(!p.escaped&&p.vehicle===null&&dist(p,{x,y})<r)p.hp-=damage});state.survivors.forEach(s=>{if(['following','waiting','boarding'].includes(s.status)&&dist(s,{x,y})<r)s.hp-=damage})}
