for(let p of state.players){if(p.hp<=0||p.escaped)continue;p.cool=Math.max(0,p.cool-dt);if(p.reloading>0){p.reloading=Math.max(0,p.reloading-dt);if(!p.reloading)p.clip=Math.min(30,p.ammo)}let i=p.input;if(p.id!==myId&&state.time-p.lastSeen>state.pace*2)i={...i,x:0,y:0,fire:false};p.angle=Math.atan2(i.ay-p.y,i.ax-p.x);let m=Math.hypot(i.x,i.y)||1,speed=p.vehicle===null?(i.sprint&&p.stamina>5?155:100):260,dx=i.x/m*speed*dt,dy=i.y/m*speed*dt;if(p.vehicle===null){if(i.sprint&&Math.hypot(i.x,i.y)>.1&&p.stamina>0)p.stamina=Math.max(0,p.stamina-dt*24);else p.stamina=Math.min(100,p.stamina+dt*16)}if(p.vehicle!==null){let v=state.vehicles[p.vehicle];if(v.hp<=0){p.vehicle=null;p.turret=false;p.hp-=30;continue}if(!p.turret){let k=1-Math.exp(-dt*3.5);v.vx=(v.vx||0)+(i.x/m*speed-(v.vx||0))*k;v.vy=(v.vy||0)+(i.y/m*speed-(v.vy||0))*k;let before={x:v.x,y:v.y};move(v,v.vx*dt,v.vy*dt,22);v.speed=dist(v,before)/Math.max(.001,dt);if(v.speed>3){let wanted=Math.atan2(v.vy,v.vx),delta=Math.atan2(Math.sin(wanted-v.angle),Math.cos(wanted-v.angle));v.angle+=Math.max(-dt*3,Math.min(dt*3,delta))}if(v.speed>20)for(let z of state.zombies){if(z.hp>0&&dist(z,v)<35){z.hp=0;if(z.explode){boom(z.x,z.y,90,90);z.detonated=true}else v.hp-=2}}}p.x=v.x;p.y=v.y}else move(p,dx,dy);if(i.fire&&!(i.sprint&&p.vehicle===null))shoot(p);for(let d of state.drops)if(d.ready&&!d.taken&&dist(p,d)<65){d.taken=true;p.ammo+=160;p.kits+=2;p.flares++;if(p.role==='engineer')p.parts=(p.parts||0)+1;event('Supplies collected: 160 rounds, 2 medkits, 1 flare.')}}
