function buildingName(b){let i=state.buildings.indexOf(b);return b.kind==='shop'?['Morrow Market','Pine & Steel Auto','Cedar Pharmacy','Haven Diner'][i%4]:b.kind==='chapel'?['Beacon Chapel','New Dawn Parish'][i%2]:'Residence '+String(i+1).padStart(3,'0')}
function start(saved=null){state=saved||makeState(+$('pace').value,$('loadout').value);myId=0;isHost=true;playing=true;paused=false;logs=[];showMap=false;viewYaw=0;lastAutoSave=performance.now();lastHP=state.players[0].hp;activate();initAudio();event('Operation active. Follow the blue distress signal. Search, protect, and return to the LZ.');}
function activate(){document.body?.classList.add('in-mission');playing=true;$('menu').style.display='none';$('hud').style.display='block';$('help').style.display=matchMedia('(pointer:coarse)').matches?'none':'block';$('actions').style.display='flex';$('banner').style.display='none';$('tutorial').style.display=tutorialDone?'none':'block';$('stick').style.display=matchMedia('(pointer:coarse)').matches?'block':'none';}
